-- Additive internal workflow, no legacy records imported or sent.
CREATE TABLE IF NOT EXISTS wf_cases(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,stage TEXT NOT NULL DEFAULT 'inquiry',revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,deal_id),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id));
CREATE TABLE IF NOT EXISTS wf_tasks(task_id TEXT PRIMARY KEY REFERENCES tasks(id),business_id TEXT NOT NULL,deal_id TEXT NOT NULL,purpose TEXT NOT NULL,basis TEXT NOT NULL,due_day TEXT NOT NULL,paused INTEGER NOT NULL DEFAULT 0,result TEXT,artifact_id TEXT REFERENCES artifacts(id),approved_by TEXT,created_at TEXT NOT NULL,FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id));
CREATE TABLE IF NOT EXISTS wf_drafts(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,deal_id TEXT NOT NULL,seminar_id TEXT NOT NULL REFERENCES seminars(id),username TEXT NOT NULL REFERENCES seminar_registrations(username),kind TEXT NOT NULL,mode TEXT NOT NULL,body TEXT NOT NULL,body_digest TEXT NOT NULL,snapshot TEXT NOT NULL,status TEXT NOT NULL,approved_by TEXT,created_at TEXT NOT NULL,UNIQUE(business_id,deal_id,seminar_id,username,kind,snapshot),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id));
CREATE TABLE IF NOT EXISTS wf_attendance(seminar_id TEXT NOT NULL REFERENCES seminars(id),username TEXT NOT NULL REFERENCES seminar_registrations(username),outcome TEXT NOT NULL,evidence TEXT NOT NULL,mode TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(seminar_id,username,mode));
CREATE TABLE IF NOT EXISTS wf_events(id INTEGER PRIMARY KEY,business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),deal_id TEXT,actor TEXT NOT NULL,event TEXT NOT NULL,ref TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS wf_one_active_draft ON wf_drafts(seminar_id,username,kind,mode) WHERE status IN ('approval_pending','send_waiting_no_api');
